package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Service;
import org.springframework.context.annotation.Lazy;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Stable warehouse identity, leased commands and query-only recovery for uncertain replies. */
@Service public class SharedReturnDocuments {
    @Resource WmsStore db;
    @Resource WmsConnections connections;
    @Resource QimenReturnProtocol protocol;
    @Resource WmsInteractionLog logs;
    @Resource @Lazy SharedReturnParcels parcels;

    void advance(String c,long parcel){advance(c,parcel,true,0);}
    void advance(String c,long parcel,boolean automatic,long expectedVersion){
        Map<String,Object> d=parcels.document(c,parcel);
        if(d!=null){if("PENDING".equals(d.get("dispatch_state"))&&"NONE".equals(d.get("cancel_state"))){send(c,parcel,"CREATE",automatic);return;}if(Arrays.asList("UNKNOWN","SENDING").contains(text(d.get("dispatch_state")))||Arrays.asList("PENDING","UNKNOWN").contains(text(d.get("cancel_state"))))send(c,parcel,"QUERY",false);return;}
        if(automatic&&db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_parcel WHERE company_code=? AND id=? AND dispatch_after<=NOW()",Long.class,c,parcel)==0)return;
        if(automatic)parcels.authorizeAll(c,parcel,"dispatch");else for(Map<String,Object> a:parcels.authority(c,parcel).values())require(Boolean.TRUE.equals(a.get("active")),"原售后申请已变化或截停，不能下发共同仓库单");
        db.tx().execute(tx->{Map<String,Object> p=db.one("SELECT * FROM wms_shared_return_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);if(parcels.document(c,parcel)!=null)return null;require(automatic||expectedVersion==id(p.get("control_version")),"包裹范围已变化，请刷新并重新确认整包下发");
            require(!automatic||db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_parcel WHERE company_code=? AND id=? AND dispatch_after<=NOW()",Long.class,c,parcel)==1,"新来源刚加入，等待完整归集时间");List<Map<String,Object>> members=parcels.members(c,parcel);require(!members.isEmpty()&&members.size()<=100,"共同退回范围不完整");List<Map<String,Object>> lines=new ArrayList<>();long qty=0;
            for(Map<String,Object> m:members){Map<String,Object> source=parcels.source(c,m,false);require("NONE".equals(source.get("cancel_state"))&&id(source.get("accepted_quantity"))==0,"来源已经截停或有独立实收，不能冻结新共同THK");require(text(source.get("payload_hash")).equals(m.get("source_hash"))&&id(source.get("shared_member_id"))==id(m.get("id")),"原来源快照或包裹归属变化");lines.add(map("line_no",text(m.get("id")),"member_id",m.get("id"),"owner_kind",m.get("owner_kind"),"owner_id",m.get("owner_id"),"owner_sn",m.get("owner_sn"),"source_id",m.get("source_id"),"task_id",m.get("task_id"),"sku_sn",m.get("sku_sn"),"quantity",m.get("quantity"),"platform_tid",p.get("platform_tid")));qty=Math.addExact(qty,id(m.get("quantity")));}
            String sn="THKX"+UUID.randomUUID().toString().replace("-","");long document=db.insert("wms_shared_return_document",map("company_code",c,"parcel_id",parcel,"return_sn",sn,"quantity",qty,"payload",db.encode(lines)));
            long ticket=db.insert("wms_tickets",map("company_code",c,"sn",sn,"business_type","AFTERSALE_IN","ticket_type",1,"original_sn",p.get("parcel_sn"),"root_order_sn",members.get(0).get("order_sn"),"relation_sn",sn,"wms_simulation_code",p.get("store_code"),"wms_simulation_name",p.get("store_code"),"real_store_code",p.get("real_store_code"),"actual_warehouse",1,"status_ticket",1,"user_name","售后合包规则","remark","退款与换货共同退回；原业务来源、数量及库存成本独立核对"));
            for(Map<String,Object> m:members){Map<String,Object> source=parcels.source(c,m,false);db.insert("wms_tickets_goods",map("company_code",c,"sn",sn,"source_line_id",m.get("id"),"inventory_type","ZP","sku_sn",m.get("sku_sn"),"goods_name",m.get("sku_sn"),"batch_code","","number_expected",m.get("quantity"),"number_actually",0,"number_dif_actually",m.get("quantity"),"purchase_price",source.get("unit_cost"),"inventory_is_handle",0));}
            db.jdbc.update("UPDATE wms_shared_return_document SET ticket_id=? WHERE company_code=? AND id=?",ticket,c,document);db.jdbc.update("UPDATE wms_shared_return_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);parcels.dirty(c,parcel);return null;
        });send(c,parcel,"CREATE",automatic);
    }
    void action(String c,long parcel,String action,Map<String,Object> input){
        if("dispatch".equals(action)){require(Boolean.TRUE.equals(input.get("confirmed_shared")),"请确认全部关联售后来源及共同下发范围");db.tx().execute(tx->{Map<String,Object> p=db.one("SELECT control_version FROM wms_shared_return_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);require(id(input.get("parcel_version"))==id(p.get("control_version")),"共同退回范围已变化，请刷新并重新确认整包下发");return null;});advance(c,parcel,false,id(input.get("parcel_version")));return;}
        Map<String,Object> d=parcels.document(c,parcel);require(d!=null,"共同包裹仍在归集，尚无实际仓库单");
        if("query".equals(action)){send(c,parcel,"QUERY",false);return;}
        db.tx().execute(tx->{Map<String,Object> p=db.one("SELECT * FROM wms_shared_return_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);Map<String,Object> current=parcels.document(c,parcel);require(id(input.get("parcel_version"))==id(p.get("control_version"))&&Boolean.TRUE.equals(input.get("confirmed_shared")),"共同THK范围已变化，请刷新并核对全部退款和换货来源");require(current.get("lease_until")==null||!java.time.LocalDateTime.parse(text(current.get("lease_until")).replace(' ','T')).isAfter(java.time.LocalDateTime.now()),"共同仓库单正在交互，请稍后查询原单");String reason=required(input,"reason",500);required(input,"evidence",1000);
            if("retry".equals(action)){require("FAILED".equals(current.get("dispatch_state"))&&"NONE".equals(current.get("cancel_state")),"仅明确失败允许重试；未知结果必须查询原单");db.jdbc.update("UPDATE wms_shared_return_document SET dispatch_state='PENDING',last_error=? WHERE company_code=? AND id=?",reason,c,current.get("id"));}
            else{require("cancel".equals(action)&&"NONE".equals(current.get("cancel_state")),"共同THK操作无效或已登记截停");db.jdbc.update("UPDATE wms_shared_return_document SET cancel_state='PENDING',last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",reason,c,current.get("id"));}
            db.jdbc.update("UPDATE wms_shared_return_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);return null;
        });send(c,parcel,"retry".equals(action)?"CREATE":"CANCEL",false);
    }
    void send(String c,long parcel,String action,boolean automatic){
        if("CREATE".equals(action)&&automatic)parcels.authorizeAll(c,parcel,"dispatch");String lease=UUID.randomUUID().toString().replace("-","");Map<String,Object> initial=parcels.document(c,parcel);if(initial==null)return;long doc=id(initial.get("id"));
        boolean claimed=db.tx().execute(tx->{db.one("SELECT id FROM wms_shared_return_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);Map<String,Object> d=parcels.document(c,parcel);if("CREATE".equals(action)&&"ACCEPTED".equals(d.get("dispatch_state")))return false;require(!"CREATE".equals(action)||"PENDING".equals(d.get("dispatch_state"))&&"NONE".equals(d.get("cancel_state")),"共同THK已有请求或截停意图，请查询原单");return db.jdbc.update("UPDATE wms_shared_return_document SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND),attempts=attempts+IF(?='CREATE',1,0),dispatch_state=IF(?='CREATE','SENDING',dispatch_state) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,action,action,c,doc)==1;});if(!claimed)return;
        long log=0,start=System.currentTimeMillis();boolean contacted=false;String secret="";
        try{Map<String,Object> p=db.one("SELECT * FROM wms_shared_return_parcel WHERE company_code=? AND id=?",c,parcel),d=parcels.document(c,parcel);Map<String,Object> connection="CREATE".equals(action)?connections.usable(c,id(p.get("connection_id"))):connections.get(c,id(p.get("connection_id")));Map<String,Object> wire=new LinkedHashMap<>(p);wire.putAll(d);wire.put("business_type","AFTERSALE_IN");wire.put("business_sn",p.get("parcel_sn"));wire.put("return_carrier",p.get("carrier_code"));wire.put("return_waybill",p.get("waybill"));wire.put("cancel_reason",d.get("last_error"));wire.put("order_lines",db.json.readValue(text(d.get("payload")),List.class));secret=connections.secret(connection);WmsProtocol.Wire request=protocol.request(connection,secret,action,wire);log=logs.start(c,id(connection.get("id")),null,text(d.get("return_sn")),"OUT","AFTERSALE_RETURN_"+action,request.body);contacted=true;WmsProtocol.Reply reply=protocol.reply(action,WmsHttp.post(request));
            require(reply.documentSn.isEmpty()||reply.documentSn.equals(d.get("return_sn")),"共同仓库单身份不一致");require(reply.externalOrder.isEmpty()||text(d.get("external_order")).isEmpty()||reply.externalOrder.equals(d.get("external_order")),"仓库受理号与原单不一致");require(reply.owner.isEmpty()||reply.owner.equals(p.get("external_owner")),"仓库货主与原来源不一致");require(reply.warehouse.isEmpty()||reply.warehouse.equals(p.get("external_warehouse")),"仓库与原接收仓不一致");if(reply.success&&!"CANCEL".equals(action)){require(!reply.externalOrder.isEmpty(),"缺少仓库受理号，请查询原单");if("QUERY".equals(action))require(reply.documentSn.equals(d.get("return_sn"))&&!reply.owner.isEmpty()&&!reply.warehouse.isEmpty(),"仓库查询身份不完整");}
            final long logId=log;db.tx().execute(tx->{db.one("SELECT id FROM wms_shared_return_parcel WHERE company_code=? AND id=? FOR UPDATE",c,parcel);require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_shared_return_document WHERE company_code=? AND id=? AND lease_token=? AND lease_until>NOW()",Long.class,c,doc,lease)==1,"共同仓库单租约失效，请查询原请求");boolean canceled="CANCEL".equals(action)||"QUERY".equals(action)&&reply.success&&"CANCELED".equals(reply.status)&&!"NONE".equals(d.get("cancel_state"));
                if(canceled){db.jdbc.update("UPDATE wms_shared_return_document SET cancel_state=?,dispatch_state=IF(?=1,'CANCELED',dispatch_state),last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",reply.success?"CONFIRMED":"REJECTED",reply.success?1:0,reply.success?"":"仓库明确拒绝共同截停",c,doc);}
                else db.jdbc.update("UPDATE wms_shared_return_document SET dispatch_state=?,external_order=IF(?='',external_order,?),warehouse_status=?,last_error=?,control_version=control_version+1 WHERE company_code=? AND id=?",reply.success?"ACCEPTED":"CREATE".equals(action)?"FAILED":d.get("dispatch_state"),reply.externalOrder,reply.externalOrder,reply.status,reply.success?"":"仓库明确拒绝请求",c,doc);
                if(reply.success)for(Map<String,Object> m:parcels.members(c,parcel)){String table=SharedReturnParcels.table(text(m.get("owner_kind")));if(canceled)db.jdbc.update("UPDATE "+table+" SET cancel_state='CONFIRMED',dispatch_state='CANCELED',cancelled_quantity=GREATEST(quantity-accepted_quantity,0),control_version=control_version+1 WHERE company_code=? AND id=?",c,m.get("task_id"));else db.jdbc.update("UPDATE "+table+" SET dispatch_state='ACCEPTED',external_order=?,warehouse_status=?,attempts=GREATEST(attempts,1) WHERE company_code=? AND id=?",reply.externalOrder,reply.status,c,m.get("task_id"));}
                db.jdbc.update("UPDATE wms_shared_return_parcel SET control_version=control_version+1 WHERE company_code=? AND id=?",c,parcel);parcels.dirty(c,parcel);logs.finish(logId,reply.success?"SUCCESS":"FAILED",db.encode(map("success",reply.success,"external_order",reply.externalOrder,"status",reply.status)),reply.success?"":"仓库明确拒绝请求",System.currentTimeMillis()-start);return null;});
        }catch(Exception failure){String why=failure instanceof IllegalArgumentException?text(failure.getMessage()):"共同仓库请求未确认，请查询原单";if(!secret.isEmpty())why=why.replace(secret,"***");db.jdbc.update("UPDATE wms_shared_return_document SET dispatch_state=IF(?='CREATE',?,dispatch_state),cancel_state=IF(?='CANCEL','UNKNOWN',cancel_state),last_error=? WHERE company_code=? AND id=? AND lease_token=?",action,contacted?"UNKNOWN":"FAILED",action,why,c,doc,lease);if(log>0)logs.finish(log,"UNKNOWN","",why,System.currentTimeMillis()-start);
        }finally{db.jdbc.update("UPDATE wms_shared_return_document SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",c,doc,lease);sync(c,parcel);}
    }
    void sync(String c,long parcel){Map<String,Object> d=parcels.document(c,parcel);if(d==null)return;long total=0,accepted=0;for(Map<String,Object> m:parcels.members(c,parcel)){Map<String,Object> source=parcels.source(c,m,false);Map<String,Object> grades=db.one("SELECT COALESCE(SUM(good_qty),0) good_qty,COALESCE(SUM(bad_qty),0) bad_qty FROM "+SharedReturnParcels.table(text(m.get("owner_kind")))+"_line WHERE company_code=? AND task_id=? AND posted=1",c,m.get("task_id"));long posted=id(source.get("posted_quantity"));total=Math.addExact(total,posted);accepted=Math.addExact(accepted,id(source.get("accepted_quantity")));db.jdbc.update("UPDATE wms_tickets_goods SET number_actually=?,number_zp=?,number_cp=?,number_dif_actually=GREATEST(number_expected-?,0),inventory_is_handle=IF(? >0,2,0),cancelled_quantity=IF(?='CONFIRMED',GREATEST(number_expected-?,0),0) WHERE UPPER(company_code)=? AND sn=? AND source_line_id=?",posted,grades.get("good_qty"),grades.get("bad_qty"),posted,posted,d.get("cancel_state"),source.get("accepted_quantity"),c,d.get("return_sn"),m.get("id"));}Map<String,Object> pending=db.one("SELECT COUNT(*) pending_count,COALESCE(SUM(quantity),0) pending_quantity FROM wms_shared_return_receipt WHERE company_code=? AND parcel_id=? AND state='WAIT_ALLOCATION'",c,parcel);db.jdbc.update("UPDATE wms_shared_return_document SET accepted_quantity=?,posted_quantity=?,pending_receipt_count=?,pending_quantity=? WHERE company_code=? AND id=?",accepted,total,pending.get("pending_count"),pending.get("pending_quantity"),c,d.get("id"));db.jdbc.update("UPDATE wms_tickets SET status_ticket=?,status_notify=?,inventory_status=?,cutoff_state=? WHERE UPPER(company_code)=? AND id=?","CONFIRMED".equals(d.get("cancel_state"))?(total>0?2:5):total==id(d.get("quantity"))?2:1,"ACCEPTED".equals(d.get("dispatch_state"))?1:0,total>0?2:0,"CONFIRMED".equals(d.get("cancel_state"))?"COMPLETED":"NONE",c,d.get("ticket_id"));}
}
